$page_title='โปรโมชันและการขาย';require_once __DIR__.'/includes/auth_check.php';requireSeller();require_once __DIR__.'/config/database.php';$db=(new Database())->getConnection();$seller=(int)$_SESSION['user_id'];$message=$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){requireCsrf(false);try{$action=$_POST['action']??'';if($action==='sale'){$id=(int)$_POST['product_id'];$price=(float)$_POST['sale_price'];$compare=(float)$_POST['compare_at_price'];$start=$_POST['starts_at'];$end=$_POST['ends_at'];if($price<=0||$compare<=$price||strtotime($end)<=strtotime($start))throw new RuntimeException('ราคาลดต้องต่ำกว่าราคาเดิม และวันสิ้นสุดต้องอยู่หลังวันเริ่ม');$q=$db->prepare('UPDATE products SET compare_at_price=?,sale_price=?,sale_starts_at=?,sale_ends_at=?,sale_stock=?,video_url=?,fulfillment_type=? WHERE id=? AND seller_id=?');$q->execute([$compare,$price,$start,$end,max(1,(int)$_POST['sale_stock']),trim($_POST['video_url']),$_POST['fulfillment_type']==='platform'?'platform':'seller',$id,$seller]);$message='บันทึก Flash Sale แล้ว';}elseif($action==='coupon'){$code=strtoupper(trim($_POST['code']));$type=$_POST['discount_type'];if(!preg_match('/^[A-Z0-9_-]{4,40}$/',$code)||!in_array($type,['percent','fixed','free_shipping'],true))throw new RuntimeException('รหัสคูปองต้องเป็น A-Z หรือตัวเลขอย่างน้อย 4 ตัว');$q=$db->prepare('INSERT INTO coupons(seller_id,code,title,description,discount_type,discount_value,min_order_amount,usage_limit,per_user_limit,starts_at,ends_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$seller,$code,trim($_POST['title']),'คูปองจากร้าน',$type,(float)$_POST['discount_value'],(float)$_POST['min_order_amount'],(int)$_POST['usage_limit']?:null,max(1,(int)$_POST['per_user_limit']),$_POST['starts_at'],$_POST['ends_at']]);$message='สร้างคูปองร้านแล้ว';}elseif($action==='bundle'){$ids=array_values(array_unique(array_map('intval',$_POST['products']??[])));if(count($ids)<2)throw new RuntimeException('เลือกสินค้าใน Bundle อย่างน้อย 2 รายการ');$db->beginTransaction();$q=$db->prepare('INSERT INTO product_bundles(seller_id,title,discount_percent,minimum_items,starts_at,ends_at) VALUES(?,?,?,?,?,?)');$q->execute([$seller,trim($_POST['title']),(float)$_POST['discount_percent'],count($ids),$_POST['starts_at'],$_POST['ends_at']]);$bundle=(int)$db->lastInsertId();$check=$db->prepare('SELECT id FROM products WHERE id=? AND seller_id=?');$add=$db->prepare('INSERT INTO product_bundle_items(bundle_id,product_id) VALUES(?,?)');foreach($ids as $id){$check->execute([$id,$seller]);if(!$check->fetchColumn())throw new RuntimeException('พบสินค้าที่ไม่ใช่ของร้าน');$add->execute([$bundle,$id]);}$db->commit();$message='สร้าง Bundle Deal แล้ว';}}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}}
$q=$db->prepare('SELECT * FROM products WHERE seller_id=? ORDER BY created_at DESC');$q->execute([$seller]);$products=$q->fetchAll();require_once __DIR__.'/includes/header.php';$start=date('Y-m-d\TH:i');$end=date('Y-m-d\TH:i',strtotime('+7 days'));?>
